const assets='assets/robot-original/';const views=[['overview','管控总览','overview.png'],['monitor','巡检监控','monitor.png'],['scenes','场景列表','scenes.png'],['deployment','场景部署','deployment.png'],['control','场景控制','control.png'],['configuration','控制配置','configuration.png'],['login','登录','login.jpeg']];const q=new URLSearchParams(location.search);let view=views.some(v=>v[0]===q.get('view'))?q.get('view'):'overview',playing=!matchMedia('(prefers-reduced-motion: reduce)').matches,still=q.get('still')==='1';if(q.get('embed')==='1')document.body.classList.add('hide-controls');const wrap=document.createElement('div');wrap.className='original-wrap';document.body.append(wrap);const controls=document.createElement('div');controls.className='original-controls';document.body.append(controls);function fit(){const ch=document.body.classList.contains('hide-controls')?0:controls.getBoundingClientRect().height;const scale=Math.min(innerWidth/1920,(innerHeight-ch)/1080);wrap.style.width=1920*scale+'px';wrap.style.height=1080*scale+'px';document.querySelector('.original-canvas').style.transform=`scale(${scale})`}
function render(){const current=views.find(v=>v[0]===view);wrap.innerHTML=`<div class="original-canvas ${!playing?'motion-paused':''} ${still?'still':''}"><img class="original-image" src="${assets+current[2]}" width="1920" height="1080" alt="${current[1]}原设计稿">${view==='overview'&&!still?'<div class="original-patch"><img src="'+assets+'background.png" alt=""></div><img class="original-core" src="'+assets+'core-alpha.png" alt="原稿中央主视觉动效层"><img class="original-satellites" src="'+assets+'satellites-alpha.png" alt="原稿周边机器人图层">':''}</div>`;controls.innerHTML=`<nav class="original-tabs" aria-label="原设计稿页面">${views.map(v=>`<button data-view="${v[0]}" role="tab" aria-selected="${v[0]===view}">${v[1]}</button>`).join('')}</nav><div class="original-actions"><span>${view==='overview'?'原主视觉轻微摆转 · 原稿其他内容保持静止':'原设计稿展示'}</span><button data-action="motion" ${view==='overview'?'':'disabled'}>${playing?'暂停动效':'播放动效'}</button><button data-action="original">${still?'查看动效':'查看静态原稿'}</button><button data-action="full">全屏</button><a href="robot.html">返回案例 ↗</a></div>`;fit();history.replaceState({},'',`?view=${view}${q.get('embed')==='1'?'&embed=1':''}${still?'&still=1':''}`)}controls.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.view){view=b.dataset.view;render();return}if(b.dataset.action==='motion'){playing=!playing;document.querySelector('.original-canvas').classList.toggle('motion-paused',!playing);b.textContent=playing?'暂停动效':'播放动效'}if(b.dataset.action==='original'){still=!still;render()}if(b.dataset.action==='full'){try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen()}catch{b.textContent='请在独立窗口查看'}}});addEventListener('resize',fit);window.OriginalRobot={setView(v){if(views.some(x=>x[0]===v)){view=v;render()}},get view(){return view},get playing(){return playing},get still(){return still}};render();
